mapper.select:
SELECT i.*, s.nickname AS seller, s.avatar AS avatar FROM item i LEFT JOIN seller s ON i.seller_id = s.id WHERE i.id IN
#{id}
ORDER BY FIELD(i.id,
#{id}
)

SELECT i.id, i.title, i.price, i.stock, i.image_url AS imageURL, i.description, i.like_count AS likeCount, i.collect_count AS collectCount, i.browser_count AS browserCount, i.brand_id AS brandId, b.name AS brand, i.category_id AS categoryId, i.category_item_id AS categoryItemId, c.name AS category, ci.item_name AS categoryItem, i.create_time AS createTime, i.seller_id AS sellerId, s.username AS seller, s.avatar AS avatar, s.location AS location FROM item i LEFT JOIN brand b ON i.brand_id = b.id LEFT JOIN category c ON i.category_id = c.id LEFT JOIN category_item ci ON i.category_item_id = ci.id LEFT JOIN seller s ON i.seller_id = s.id
AND i.status = 1 AND i.stock > 0
AND ( i.title LIKE CONCAT('%',#{keyword},'%') OR i.description LIKE CONCAT('%',#{keyword},'%') )
AND i.category_id = #{categoryId}
AND i.category_item_id = #{categoryItemId}
AND i.brand_id = #{brandId}
AND i.price >= #{minPrice}
AND i.price <= #{maxPrice}
ORDER BY i.price ASC, i.create_time DESC, i.id DESC
ORDER BY i.price DESC, i.create_time DESC, i.id DESC
ORDER BY i.create_time DESC, i.id DESC
LIMIT #{limit}
